-- 热管理材料 7 家 + 光通信芯片/设备 8 家 纳入研究池 (2026-10-15)

INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'钜瓷科技',null,'semiconductor','material',false,'C 轮',null,null,null,'2025','{"name":"钜瓷科技","industry":"semiconductor","seg":"material","listed":false,"desc":"厦门钜瓷科技有限公司（2016-12-27 成立，总部厦门翔安，法定代表人管军凯），首席科学家为北京科技大学秦明礼教授，是国内首家、也是目前唯一具备合格高品级氮化铝粉末批量制备能力的企业。氮化铝（AlN）导热与绝缘性能俱佳，是功率半导体、高功率 LED、高铁与新能源汽车 IGBT、激光器芯片等高端装备必需的关键散热材料，长期被日本德山等企业垄断，工信部列为战略基础原材料。公司依托北科大近 20 年研究成果，掌握湿法混料与自主研发的短流生产工艺，实现国产替代——相较海外龙头可不依赖高纯原料，单位时间产能为德山的两倍，每公斤能耗降低 60%、成本降低 50%。主要产品包括高纯微细氮化铝粉末、球形氮化铝颗粒、复杂精密氮化铝陶瓷制品三大系列，另有注射成形氮化铝陶瓷技术处于世界领先水平。2024 年氮化铝粉体年产能达 600 吨、国内市场占有率约 70%、位居全球第二；2025 年内蒙古基地一期正式投产，规划年产 5000 吨电子陶瓷粉体，达产后产能将居全球第一。2025 年全球氮化铝陶瓷基板市场规模约 13.65 亿元（中国市场 2.91 亿元），国产化替代趋势明确。公司为国家级专精特新「小巨人」、国家重点研发计划负责单位，2017 年获第六届中国创新创业大赛新材料行业总决赛初创组一等奖。","round":"C 轮","lastFunding":"2025","latestFunding":"C 轮，投资方包括深创投、比亚迪、湖杉资本、中科创星等。此前 B+ 轮由湖杉资本领投，再石资本、厦门火炬集团、启高资本、华强创投等跟投，资金用于扩充生产线及产能。","latestTech":"高品级氮化铝粉末制备技术实现从 0 到 1 突破，产品可比肩日本德山公司且部分指标更优；注射成形氮化铝陶瓷生产技术处于世界领先水平。","tech":[{"date":"2025","title":"内蒙古基地一期投产，规划年产 5000 吨电子陶瓷粉体","kind":"产能","desc":"填补呼和浩特高端电子陶瓷材料产业空白，规模化量产提升国内供应链自主能力。"},{"date":"2024","title":"氮化铝粉体年产能达 600 吨，国内市场占有率 70%","kind":"量产","desc":"产能及销售规模位列全球第二，仅次于日本德山。"}],"funding":[{"date":"2025","round":"C轮","inv":"深创投、比亚迪、湖杉资本、中科创星等"},{"date":"2024","round":"B+轮","amount":"未披露","inv":"湖杉资本（领投）、再石资本、厦门火炬集团、启高资本、华强创投等"},{"date":"2023","round":"B轮","inv":"向日葵投资、中科创星、比亚迪、富乐华、湖杉资本等"},{"date":"2017","round":"天使轮","amount":"600万元","inv":"厦门高新投"}],"investorsStructured":[{"name":"深创投","role":"lead","round":"C轮","date":"2025","kind":"vc"},{"name":"比亚迪","role":"strategic","round":"B轮/C轮","date":"2023","kind":"cvc","note":"动力电池与功率器件散热需求方"},{"name":"湖杉资本","role":"lead","round":"B+轮","date":"2024","kind":"vc","note":"半导体材料赛道专业基金"},{"name":"中科创星","role":"follow","round":"B轮","date":"2023","kind":"vc","note":"中科院西安光机所背景硬科技基金"},{"name":"富乐华","role":"strategic","round":"B轮","date":"2023","kind":"cvc","note":"覆铜陶瓷基板厂商"},{"name":"厦门火炬集团","role":"follow","round":"B+轮","date":"2024","kind":"gov","note":"厦门火炬高新区国资平台"},{"name":"厦门高新投","role":"lead","round":"天使轮","date":"2017","kind":"gov","note":"厦门高新区国资，首轮投资 600 万元"},{"name":"再石资本","role":"follow","round":"B+轮","date":"2024","kind":"vc"},{"name":"启高资本","role":"follow","round":"B+轮","date":"2024","kind":"vc"},{"name":"华强创投","role":"follow","round":"B+轮","date":"2024","kind":"vc"},{"name":"向日葵投资","role":"follow","round":"B轮","date":"2023","kind":"vc"}],"executives":[{"name":"管军凯","title":"法定代表人","role":"management","bio":"钜瓷科技法定代表人，2016 年与秦明礼等共同创立公司，推动氮化铝粉体产业化落地。"},{"name":"秦明礼","title":"首席科学家","role":"management","bio":"北京科技大学教授，攻读博士期间即从事氮化铝研究，二十余年积累；带领团队实现高品级氮化铝粉末制备技术从 0 到 1 的突破，公司技术源头。"}],"note":"氮化铝陶瓷基板属 AI 算力与功率半导体散热的关键上游材料，国产化率提升空间大。同类可参照池内「石英 / 陶瓷部件」leaf 的德智新材、灿勤科技。"}'::jsonb,now()
)
