INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'墨睿科技',null,'semiconductor','material',false,'C 轮',null,null,null,'2026-06','{"name":"墨睿科技","industry":"semiconductor","seg":"material","listed":false,"desc":"广东墨睿科技有限公司（2015-10 成立，总部东莞），由多名国家引进海外高层次人才领衔，团队含 4 名国家级高端人才、2 名省级高端人才及 40 余位硕博士。创始人蔡金明 22 岁北京大学本科毕业、27 岁中科院物理所博士毕业，后在美国橡树岭国家实验室与瑞士联邦材料科学与技术研究所留学六年，34 岁成为昆明理工大学博士生导师；在石墨烯领域创造三项「世界第一」，包括世界首创以自下而上方法制备结构可控、原子级精准的石墨烯纳米带材料，并首次用实验证明石墨烯纳米带的径向呼吸模型。公司是全球首家完成石墨烯原料生产到导热膜制备全链条生产的企业，破解了「懂原料的不会做膜、会做膜的受制于原料」的行业长期矛盾。产品矩阵覆盖石墨烯导热膜、石墨烯相变均温板、石墨烯 TIM 膜、柔性石墨烯膜等，应用于 3C 消费电子、高功率芯片、算力服务器、通讯基站等领域。石墨烯 TIM 热导率高达 130W/(m·K)，远超传统导热相变材料的 8.5W/(m·K)。公司已深度嵌入小米供应链——小米 MIX Flip2 采用其高性能超柔性石墨烯导热膜，散热效率较传统材料提升 30% 以上；小米 AI 眼镜采用其零包边石墨烯导热膜。专利已在中、日、美、欧完成布局，授权和受理 100 余项中国专利。","round":"C 轮","lastFunding":"2026-06","latestFunding":"C 轮，小米产投、中车时代高新投资、广发信德、势能资本、哇牛资本、昆仑投资等机构集体入局；工商变更显示新增北京小米智造股权投资基金合伙企业为股东，注册资本增至约 2202.42 万人民币。","latestTech":"石墨烯 TIM 膜热导率达 130W/(m·K)，为传统导热相变材料（8.5W/(m·K)）的 15 倍以上；英伟达新一代 Rubin GPU 已全面切换使用石墨烯 TIM 材料，2026 年 Q4 有望逐步放量。","tech":[{"date":"2026","title":"石墨烯 TIM 材料切入 AI 算力散热","kind":"应用","desc":"英伟达 Rubin 架构 GPU 全面切换石墨烯 TIM，带动石墨烯导热薄膜市场扩容。"},{"date":"2025","title":"石墨烯导热膜导入小米旗舰与 AI 眼镜","kind":"量产","desc":"MIX Flip2 超柔性石墨烯导热膜散热效率提升 30% 以上；AI 眼镜采用零包边方案攻克微型穿戴散热瓶颈。"}],"funding":[{"date":"2026-06","round":"C轮","inv":"小米产投、中车时代高新投资、广发信德、势能资本、哇牛资本、昆仑投资等"},{"date":"2019","round":"早期轮次","inv":"小米（首次投资，此后至少连投三轮）"}],"investorsStructured":[{"name":"小米产投","role":"strategic","round":"C轮","date":"2026-06","kind":"cvc","note":"自 2019 年起至少第三次投资，锁定「人车家」生态散热材料供应"},{"name":"中车时代高新投资","role":"strategic","round":"C轮","date":"2026-06","kind":"cvc","note":"中车系产投，打开功率器件与轨道交通散热场景"},{"name":"广发信德","role":"follow","round":"C轮","date":"2026-06","kind":"pe"},{"name":"势能资本","role":"follow","round":"C轮","date":"2026-06","kind":"vc"},{"name":"哇牛资本","role":"follow","round":"C轮","date":"2026-06","kind":"vc"},{"name":"昆仑投资","role":"follow","round":"C轮","date":"2026-06","kind":"vc"}],"executives":[{"name":"蔡金明","title":"创始人","role":"management","bio":"北京大学本科、中科院物理所博士，美国橡树岭国家实验室与瑞士联邦材料科学与技术研究所留学六年，曾任昆明理工大学博士生导师；石墨烯领域三项「世界第一」创造者，首创自下而上制备原子级精准石墨烯纳米带材料。"}],"note":"国内石墨烯导热薄膜行业第一梯队（与常州富烯、深圳稀导并列），池内「封装材料」leaf 已有富烯科技，可对照跟踪。"}'::jsonb,now()
)
