INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'巡航新材料',null,'semiconductor','material',false,'A 轮',null,null,null,'2026-07','{"name":"巡航新材料","industry":"semiconductor","seg":"material","listed":false,"desc":"巡航（苏州）新材料技术有限公司（2024-06 成立，注册地江苏苏州相城经济开发区），是国内极端环境专用复合材料自主研发与产业化企业，定位「尖端装备用先进功能材料平台型企业」，核心使命是突破航空航天、低空装备、新能源高端热管理、电磁隐身领域关键材料「卡脖子」技术。创始人李宜彬（硕士），深耕石墨烯、碳素复合、高温隔热材料行业十余年，曾长期从事碳素复合材料工业化工艺开发，解决石墨金属异质钎焊、气凝胶规模化成型等行业共性难题，直接或间接控股超 10 家新材料与投资类企业；2023 年牵头设立山东巡航新材料搭建量产产线，2024 年落地苏州研发总部。三条协同产品线：①航天/军工热管理材料——采用石墨烯有序化组装技术，形成高度有序的三维石墨烯多孔骨架、块体材料及二维薄膜材料，做出高导热快响应相变储能复合材料、低热阻柔性石墨烯导热垫片、三明治结构石墨烯均热板、柔性石墨烯导热链等产品，已批量供货并配套多型商用卫星在轨项目；②高温热防护材料——独创陶瓷纳米纤维气凝胶技术路线，适配高速飞行器、可回收运载火箭、第四代核能等超高温极端工况；③结构功能一体化复合材料。四大底层技术平台为纳米复合分散、一体化成型、异质材料连接、多功能协同调控。","round":"A 轮","lastFunding":"2026-07","latestFunding":"A 轮 亿元级，由毅达资本、十月资本、中银国际投资、中科神光等机构联合参投。","latestTech":"石墨烯有序化组装技术，将石墨烯纳米片宏观组装形成三维多孔骨架与二维薄膜，解决纳米片级优异性能向宏观器件尺度放大的产业化核心难点；独创陶瓷纳米纤维气凝胶路线，解决传统气凝胶高温易坍塌、陶瓷隔热瓦密度大的痛点。","tech":[{"date":"2026","title":"多条产品线实现小批量下游供货","kind":"量产","desc":"高导热热管理、高温热防护、电磁功能三大系列产品全部实现小批量供货，配套多型商用卫星在轨项目。"}],"funding":[{"date":"2026-07","round":"A轮","amount":"亿元级","inv":"毅达资本、十月资本、中银国际投资、中科神光等联合参投"}],"investorsStructured":[{"name":"毅达资本","role":"lead","round":"A轮","date":"2026-07","kind":"vc","note":"江苏高投旗下，半导体材料领域活跃"},{"name":"十月资本","role":"follow","round":"A轮","date":"2026-07","kind":"vc"},{"name":"中银国际投资","role":"follow","round":"A轮","date":"2026-07","kind":"pe","note":"银行系 AIC 基金"},{"name":"中科神光","role":"follow","round":"A轮","date":"2026-07","kind":"vc","note":"中科院背景"}],"executives":[{"name":"李宜彬","title":"创始人","role":"management","bio":"硕士学历，深耕石墨烯、碳素复合、高温隔热材料行业十余年，解决石墨金属异质钎焊、气凝胶规模化成型等行业共性难题；直接控股哈尔滨烯创科技、哈尔滨巡航新材料，间接持有苏州巡航、山东巡航新材料 65.35% 股权。"}],"note":"成立仅两年即完成亿元级 A 轮，产品从航天军工向民用热管理延伸，属平台型材料企业。"}'::jsonb,now()
)
