INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'瑞为新材',null,'semiconductor','material',false,'B 轮',null,null,null,'2025-02','{"name":"瑞为新材","industry":"semiconductor","seg":"material","listed":false,"desc":"南京瑞为新材料科技有限公司（2021-12-24 成立，总部南京市六合区南航国际创新港，法定代表人王长瑞），新一代金刚石/金属新型芯片散热材料产业化的探索者与创新者，与南京航空航天大学开展产学研合作。金刚石是自然界导热性能最好的材料（室温热导率约 2000-2200W/(m·K)，为铜的 5 倍），但金刚石与铜不相容、直接接触会产生不浸润现象（「如水滴到荷叶上」），团队在实验室攻关近 3 年找到有效结合的新型配方，突破金属与金刚石表面异质润湿工艺、精密成型技术、多梯度一体化制造技术，做出导热性能达传统材料 3-5 倍的金刚石/金属复合材料。产品三代迭代：第一代平面载片类（导热能力较普通材料提升 275%-300%，可使芯片温升降低 20-30℃）；第二代壳体类（芯片热沉+壳体一体化封装，减小热阻并省去一道焊接工序）；第三代冷板类（集成散热片、管壳、散热器，搭配 GPU 微流道设计，实现「液冷+导热」双效散热）。公司是国内首家实现金刚石散热材料批量供货的企业，产品应用于卫星、战斗机、航母、新能源汽车等「大国重器」供应链，服务十大军工集团及华为、中兴等龙头。截至 2025 年 12 月已完成四轮以上融资、估值近十亿元，2025 年获评国家级专精特新「小巨人」。","round":"B 轮","lastFunding":"2025-02","latestFunding":"B 轮，由君联资本投资。另据披露，A++ 轮由君联资本、中车资本（工信部制造业转型升级基金）等参与。截至 2025 年 12 月公司已完成四轮以上融资，累计融资金额数亿元，估值近十亿元。","latestTech":"金刚石/金属复合材料导热性能达传统散热片的 3-5 倍，且热膨胀系数与半导体材料匹配；独创金属与金刚石表面异质润湿工艺与多梯度一体化制造技术，解决复合材料制备与金刚石机加工难题。","tech":[{"date":"2025","title":"第三代封装一体化冷板量产","kind":"量产","desc":"集成散热片、管壳、散热器，搭配 GPU 微流道设计，实现「液冷+导热」双效散热。"},{"date":"2024","title":"金刚石散热材料批量供货大国重器供应链","kind":"量产","desc":"成为国内首家实现金刚石散热材料批量供货的企业，进入卫星、战斗机、航母供应链。"}],"funding":[{"date":"2025-02","round":"B轮","inv":"君联资本"},{"date":"2024-06","round":"A+轮","amount":"数千万元","inv":"毅达资本（领投）、南创投、恺富资本（跟投）"},{"date":"2023-01","round":"A轮","amount":"数千万元","inv":"明智资本 5G 产业投资基金（领投）、水木创投（跟投）"},{"date":"2021-12","round":"天使轮","amount":"千万元","inv":"无限基金 SEE Fund、欣和资本"}],"investorsStructured":[{"name":"君联资本","role":"lead","round":"B轮","date":"2025-02","kind":"vc"},{"name":"中车资本","role":"strategic","round":"A++轮","date":"2025","kind":"cvc","note":"工信部制造业转型升级基金"},{"name":"毅达资本","role":"lead","round":"A+轮","date":"2024-06","kind":"vc"},{"name":"南创投","role":"follow","round":"A+轮","date":"2024-06","kind":"gov","note":"南京市创新投资集团"},{"name":"恺富资本","role":"follow","round":"A+轮","date":"2024-06","kind":"vc"},{"name":"明智资本","role":"lead","round":"A轮","date":"2023-01","kind":"vc","note":"5G 产业投资基金"},{"name":"水木创投","role":"follow","round":"A轮","date":"2023-01","kind":"vc","note":"清华系"},{"name":"无限基金 SEE Fund","role":"lead","round":"天使轮","date":"2021-12","kind":"vc","note":"清华电子系背景"},{"name":"欣和资本","role":"follow","round":"天使轮","date":"2021-12","kind":"vc"}],"executives":[{"name":"王长瑞","title":"董事长","role":"board","bio":"「80 后」博士，2021 年 12 月带领团队带专利技术落户南京六合高新区创立瑞为新材，主导金刚石/金属复合材料芯片热沉产业化核心技术攻关。"}],"note":"金刚石铜复合材料是英伟达 Vera Rubin 架构明确采用的散热方案（金刚石铜复合材料+液冷），2026 年被视为金刚石散热「刚需元年」。中泰证券预测 2026 年全球高端 AI 芯片用金刚石散热片市场规模 87 亿元，2030 年达 592 亿元。"}'::jsonb,now()
)
