INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'博志金钻',null,'semiconductor','material',false,'战略融资',null,null,null,'2026-04','{"name":"博志金钻","industry":"semiconductor","seg":"material","listed":false,"desc":"苏州博志金钻科技有限责任公司（2020-03-31 成立，总部苏州高新区，曾用名陕西博志金钻新材料有限责任公司，法定代表人潘远志），专注于半导体封装热沉材料与器件研发生产，解决高功率芯片散热及高密度集成封装挑战。创始人潘远志 2001 年出生、江苏徐州人，15 岁考入西安交大少年班，2017 年尚在读大学时即开始新材料医疗器械领域创业（微针产品，融资 3500 万元），2020 年 3 月回到苏州二次创业创立博志金钻，凭「金镶钻」项目 2020 年三次登上央视，2025 年 24 岁获评「苏州青年科学家」，曾入选福布斯中国「30 岁以下精英榜」。公司技术研发由中国科学院院士孙军教授与国家万人计划领军人才宋忠孝教授领衔，核心团队多来自西安交大材料学院。以物理气相沉积（PVD）工艺为核心，自研 PVD 连续镀技术（纳米级磁控溅射让金属离子精准附着陶瓷表面）、微纳图形化与通孔互连、金刚石表面金属化等，具备抛光、镀膜到光刻、刻蚀、切割全流程产线。核心产品为陶瓷封装载板，基材涵盖氮化铝、氧化铝、碳化硅、金刚石基，线宽 1-2μm（远低于传统 50μm），导热率 180-500W/m·K。拥有超 38 项专利，在苏州、南通、临沂、许昌建有四座量产工厂，总厂房超 2 万平方米，月产 5 亿颗、年产能 60 万板。客户涵盖苹果、中际旭创、光迅科技、极米等 80 余家国内外龙头。2025 年全球陶瓷载板市场约 120 亿元（中国约 45 亿元）。","round":"战略融资","lastFunding":"2026-04","latestFunding":"2026-04 新一轮融资，由智连资本独家投资。此前 2024-11 完成数千万人民币 B 轮融资，由昆高新创投领投。公司累计融资金额超 1 亿元，估值达 8 亿元。","latestTech":"PVD 连续镀技术通过纳米级磁控溅射让金属离子精准附着陶瓷表面，解决陶瓷与金属结合力弱、热膨胀失配难题；陶瓷封装载板线宽 1-2μm、导热率 180-500W/m·K，导热率比国外同类产品高 22%。","tech":[{"date":"2025","title":"高功率芯片陶瓷载板全线拉通量产","kind":"量产","desc":"苏州基地前道精密加工、南通基地后道关键工序，建成超 1.5 万平方米万级洁净车间。"},{"date":"2020","title":"「金镶钻」高性能芯片散热材料项目三次登上央视","kind":"研发","desc":"创始人潘远志主导的散热材料项目获 500 万元天使轮投资。"}],"funding":[{"date":"2026-04","round":"战略融资","inv":"智连资本（独家）"},{"date":"2024-11","round":"B轮","amount":"数千万元","inv":"昆高新创投（领投）"},{"date":"2022","round":"A轮","inv":"未披露"},{"date":"2021","round":"Pre-A轮","inv":"未披露"},{"date":"2020","round":"天使轮","amount":"500万元","inv":"未披露"}],"investorsStructured":[{"name":"智连资本","role":"lead","round":"战略融资","date":"2026-04","kind":"vc","note":"独家投资"},{"name":"昆高新创投","role":"lead","round":"B轮","date":"2024-11","kind":"gov","note":"昆山高新区国资"},{"name":"苏高新金控","role":"follow","round":"早期","date":"2022","kind":"gov","note":"苏州高新区国资平台"},{"name":"融享创投","role":"follow","round":"早期","date":"2022","kind":"vc"},{"name":"苏州高新区科创天使基金","role":"follow","round":"早期","date":"2021","kind":"gov"}],"executives":[{"name":"潘远志","title":"创始人","role":"management","bio":"2001 年出生，15 岁考入西安交大少年班，2020 年创立博志金钻；2025 年 24 岁获评「苏州青年科学家」，曾入选福布斯中国「30 岁以下精英榜」、胡润「U35 中国创业先锋」，获教育部第十六届「中国大学生年度人物」。同时担任南通志芯科技等多家企业法定代表人。"},{"name":"孙军","title":"首席科学家（技术研发领衔）","role":"board","bio":"中国科学院院士，领衔公司技术研发，与西安交通大学深度合作。"},{"name":"宋忠孝","title":"技术研发领衔","role":"board","bio":"国家万人计划领军人才，潘远志在西安交大的导师，与孙军院士共同领衔公司技术研发。"}],"note":"陶瓷封装载板同时服务光通信模块（中际旭创、光迅科技）与功率器件（新能源车 IGBT），是「热管理材料」与「IC 载板」的交叉标的。"}'::jsonb,now()
)
