INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'墨锋科技',null,'semiconductor','material',false,'战略融资',null,null,null,'2026-06','{"name":"墨锋科技","industry":"semiconductor","seg":"material","listed":false,"desc":"苏州墨锋新材料科技有限公司（2023 年成立，总部苏州），技术源自四川大学近 20 年的高分子材料研究成果，团队聚焦高性能 POD（聚芳噁二唑）薄膜产业化。POD 作为一种耐高温聚合物，早在上世纪六七十年代便受到关注，但因加工成型工艺复杂和设备腐蚀问题，产业化难度极高；国内系统性研究起步较晚但进展迅速，2006 年前后四川大学徐建军教授团队开始推进研究。墨锋科技核心团队来自徐建军教授课题组，创始人李文涛拥有丰富产业化经验，联合创始人姜猛进（四川大学教授）长期深耕 POD 高性能化研究。公司优化成型工艺，提高材料模量与结晶度、增强膜材刚性，并实现成卷烧制，大幅降低成本、提升致密性并有效改善掉粉问题。产品性能领先：原膜力学性能好、初始膜量可达 4.0GPa，拉伸强度大于 200MPa，成膜厚度超 400μm，石墨化并压延后厚度最高可达 200μm；经下游客户验证，POD 石墨膜热扩散系数大于 1000mm²/s，石墨化后导热系数可达 2000W/(m·K)。战略上采取「双轨布局」：以消费电子为基础市场（5G 手机、折叠屏设备石墨膜前驱体），拓展 AI 芯片与光模块 TIM 材料领域（通过高发泡产品加工制备芯片导热界面材料）。当前年产能约 100 吨，单一订单规模已达数十吨，规划新增 300-500 吨/年产线。","round":"战略融资","lastFunding":"2026-06","latestFunding":"2026-06 完成新一轮千万元融资，由险峰基金、成都科创投集团投资，资金主要用于产线扩建与产能扩张。","latestTech":"POD 基导热泡沫方案可实现 >1000W/(m·K) 的导热系数，优于石墨烯方案（约 900W/(m·K)），且具备更好的可加工性；传统 TIM 材料（如导热硅脂）导热系数通常小于 10W/(m·K)，难以满足大功率芯片需求。","tech":[{"date":"2026","title":"POD 膜切入 AI 芯片与光模块 TIM 上游原膜","kind":"应用","desc":"通过高发泡产品加工制备芯片导热界面材料，多家头部手机厂商表现出较强导入意愿。"}],"funding":[{"date":"2026-06","round":"战略融资","amount":"千万元","inv":"险峰基金、成都科创投集团"}],"investorsStructured":[{"name":"险峰基金","role":"lead","round":"战略融资","date":"2026-06","kind":"vc"},{"name":"成都科创投集团","role":"follow","round":"战略融资","date":"2026-06","kind":"gov","note":"成都国资科创投资平台"}],"executives":[{"name":"李文涛","title":"创始人","role":"management","bio":"拥有丰富的 POD 材料产业化经验，主导墨锋科技 POD 膜工艺优化与产线建设。"},{"name":"姜猛进","title":"联合创始人","role":"management","bio":"四川大学教授，徐建军教授课题组成员，长期深耕 POD 高性能化研究。"}],"note":"产品核心壁垒在制膜溶液与膜片制备环节，涉及大量 Know-how；膜片制备形成「湿法单向扩散」工艺。"}'::jsonb,now()
)
