INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'稀导技术',null,'semiconductor','material',false,'未融资',null,null,null,null,'{"name":"稀导技术","industry":"semiconductor","seg":"material","listed":false,"desc":"深圳稀导技术有限公司（2019-11-01 成立，总部深圳市南山区科技园，法定代表人曾菁，注册资本 4000 万人民币），聚焦石墨烯散热材料的研发、制造与应用，提供一站式散热解决方案，是国家专精特新「小巨人」企业、国家高新技术企业、广东省专精特新中小企业、深圳市瞪羚企业。主要产品包括石墨烯散热薄膜、石墨烯散热基板、石墨烯导热垫片、超薄 VC 均温板等，广泛应用于消费电子、新能源汽车电池、5G 通讯、AI 算力芯片、光通讯及工业类电子产品等行业。生产布局上，深圳设总部，江西上饶建石墨烯原膜生产基地，广东中山建后端模切精加工基地，形成全产业链整合能力。拥有自主研发实验室，专利信息约 80-88 条，其中发明专利占比高。客户群体已与 40 多家上市公司及行业龙头企业合作，覆盖国内主流手机终端商及 ODM 厂商。与常州富烯、广东墨睿共同代表国内石墨烯导热薄膜行业第一梯队。公司目前尚未进行外部融资，属民营企业中的异军突起，强调全产业链整合与高端定制能力。","round":"未融资","latestFunding":"公司目前尚未融资，属民营企业中的异军突起，强调全产业链整合与高端定制能力。","latestTech":"覆盖石墨烯散热薄膜、散热基板、导热垫片、超薄 VC 均温板全品类；拥有自主研发实验室，专利约 80-88 条且发明专利占比高。","executives":[{"name":"曾菁","title":"法定代表人","role":"management","bio":"稀导技术法定代表人，公司未引入外部融资，依靠自有资金完成深圳总部、江西上饶原膜基地与广东中山模切基地的全产业链布局。"}],"note":"国内石墨烯导热薄膜第一梯队中唯一未融资企业，可作为一级市场潜在标的观察对象。"}'::jsonb,now()
)
