INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'熹联光芯',null,'semiconductor','design',false,'B5 轮',null,null,null,'2026-05','{"name":"熹联光芯","industry":"semiconductor","seg":"design","listed":false,"desc":"常州熹联光芯微电子科技有限公司（2020-07-20 成立，法定代表人李晓军，2025 年 4 月总部由苏州迁入江苏常州武进国家高新区），由半导体、硅光及金融等领域多位资深专家领头，专注全集成化硅光芯片核心技术研发的高新技术企业，致力于打造硅光领先技术平台。公司掌握硅光全链条核心能力，覆盖芯片设计、流片工艺、晶圆测试、光引擎开发等环节，拥有百余项核心专利。2021 年 10 月完成对德国硅光企业 Sicoya GmbH 100% 股权并购，搭建上海、柏林两大研发中心，形成中欧协同的全球化研发体系。产品可提供硅光芯片、模拟电芯片、光电共封芯片等核心产品，400G、800G 至 1.6T 全系列硅光芯片已向国内外头部客户批量供货，其中 1.6T 系列硅光产品进入批量交付阶段，并切入部分全球头部客户供应链体系，技术路线同时覆盖下一代 CPO 共封装光学应用需求。在 OFC 2026 光纤通信大会上集中展示基于单通道 200G 硅光技术的 1.6T 光模块系列产品，并与业界主流交换设备厂商完成互联互通演示；已实现单波 200G 硅光芯片量产导入，在单通道 400G、CPO、NPO 及收端芯片等前沿方向完成技术储备。产能方面，杭州第二座亚洲工厂计划 2026 年 5 月投运，墨西哥蒙特雷北美制造基地预计 2026 年第三季度启用，届时全球制造能力有望达每月数十万件规模。2026 年 4 月在常州签约总投资 10 亿元硅光芯片及器件研发制造基地项目，达产后预计年销售额 20 亿元、年入库税收 2 亿元。","round":"B5 轮","lastFunding":"2026-05","latestFunding":"B5 轮 数亿元，本轮由永鑫方舟领投，产业资本、头部人民币基金、头部美元基金等多家知名机构共同参与。资金用途官方未披露，企业表示将持续推进硅光芯片技术研发与产能建设。本轮为多轮融资延续，此前已完成 A 轮、B 轮、B+ 轮、C 轮、C+ 轮、D 轮等多轮融资。","latestTech":"掌握硅光全链条核心能力（芯片设计、流片工艺、晶圆测试、光引擎开发），累计拥有百余项核心专利；单波 200G 硅光芯片已量产导入，1.6T 系列批量交付，并在单通道 400G、CPO、NPO 及收端芯片方向完成技术储备。","tech":[{"date":"2026-05","title":"OFC 2026 展示单通道 200G 硅光 1.6T 光模块并完成互通演示","kind":"技术","desc":"与业界主流交换设备厂商完成互联互通演示，1.6T 系列硅光产品进入批量交付阶段。"},{"date":"2026-04","title":"常州 10 亿元硅光芯片及器件研发制造基地项目签约","kind":"产能","desc":"布局高速硅光通信芯片测试分选产线，达产后预计年销售额 20 亿元、年入库税收 2 亿元。"},{"date":"2021-10","title":"100% 股权并购德国 Sicoya GmbH","kind":"并购","desc":"搭建上海、柏林双研发中心，形成中欧协同的全球化研发体系。"}],"funding":[{"date":"2026-05","round":"B5轮","amount":"数亿元","inv":"永鑫方舟（领投），产业资本、头部人民币基金及美元基金等多家机构参与"},{"date":"2026-04","round":"D轮","inv":"永鑫方舟、澜起投资、柘中股份、追远创投、深创投、福州盈峰"},{"date":"2024","round":"C+轮","inv":"中山创投"},{"date":"2024","round":"C轮","inv":"武高新、国经资本"},{"date":"2023-09","round":"B+轮","amount":"数亿元","inv":"昆仑资本、弘毅投资、亨通光电、创投汽车"},{"date":"2023-01","round":"B轮","amount":"数亿元","inv":"芯鑫租赁、建信信托、芯动能基金、武岳峰资本、Copious Gain Global、疆亘资本、Hawksburn VCC、昆仑资本、招商资本、Partners Group"},{"date":"2022-06","round":"战略投资","inv":"畅视通科技、聚飞光电、大唐电信、临芯投资、一村资本、高榕资本、Smart Page Holding、建华开源私募基金、华熙投资、益新投资、中青芯鑫、哈勃投资"},{"date":"2021","round":"早期轮次","inv":"昆玉资本（战略投资）"}],"investorsStructured":[{"name":"永鑫方舟","role":"lead","round":"B5轮","date":"2026-05","kind":"vc","note":"连续参与 D 轮与 B5 轮，苏州本土半导体基金"},{"name":"哈勃投资","role":"strategic","round":"战略投资","date":"2022-06","kind":"cvc","note":"华为旗下，早期卡位硅光芯片"},{"name":"深创投","role":"follow","round":"D轮","date":"2026-04","kind":"vc"},{"name":"澜起投资","role":"strategic","round":"D轮","date":"2026-04","kind":"cvc","note":"澜起科技旗下，与硅光互连协同"},{"name":"柘中股份","role":"strategic","round":"D轮","date":"2026-04","kind":"cvc","note":"上市公司产业投资"},{"name":"武岳峰资本","role":"follow","round":"B轮","date":"2023-01","kind":"vc","note":"半导体专业基金"},{"name":"招商资本","role":"follow","round":"B轮","date":"2023-01","kind":"pe"},{"name":"昆仑资本","role":"lead","round":"B+/B轮","date":"2023-09","kind":"pe","note":"连续参与 B 轮与 B+ 轮"},{"name":"建信信托","role":"follow","round":"B轮","date":"2023-01","kind":"pe","note":"银行系，通过芯鑫租赁参与"},{"name":"弘毅投资","role":"follow","round":"B+轮","date":"2023-09","kind":"pe"},{"name":"亨通光电","role":"strategic","round":"B+轮","date":"2023-09","kind":"cvc","note":"光通信产业方"},{"name":"临芯投资","role":"follow","round":"战略投资","date":"2022-06","kind":"vc","note":"半导体专业基金"},{"name":"高榕资本","role":"follow","round":"战略投资","date":"2022-06","kind":"vc"},{"name":"大唐电信","role":"strategic","round":"战略投资","date":"2022-06","kind":"cvc"},{"name":"一村资本","role":"follow","round":"战略投资","date":"2022-06","kind":"pe"},{"name":"聚飞光电","role":"strategic","round":"战略投资","date":"2022-06","kind":"cvc"},{"name":"武进高新投","role":"follow","round":"C轮","date":"2024","kind":"gov","note":"武进高新区国资"}],"executives":[{"name":"李晓军","title":"法定代表人","role":"management","bio":"熹联光芯法定代表人，主导公司硅光技术平台建设与全球化产能布局。"}],"note":"2026 年硅光在光模块中渗透率预计首次超过 50%（两年前为 33%），硅光方案功耗与成本较传统 EML 低 10%-20%。同赛道可对照池内光联芯科、铌奥光电。"}'::jsonb,now()
)
