INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'国科光芯',null,'semiconductor','design',false,'B+ 轮',null,null,null,'2026-09','{"name":"国科光芯","industry":"semiconductor","seg":"design","listed":false,"desc":"国科光芯（海宁）科技股份有限公司（2019-04 成立，总部浙江海宁），国内少数以氮化硅（SiN）硅光材料为技术底座的硅光芯片企业，集材料工艺、芯片设计、集成封装、光电子器件、应用算法、系统集成等综合能力于一体。创始人刘敬伟博士是中国科学院半导体研究所 2005 届微电子学与固体电子学博士（师从余金中博导），毕业后长期任职于京东方，后创立国科光芯。氮化硅硅光平台具备超低传输损耗、超高光学功率承载能力与 CMOS 工艺兼容性，被视为突破传统分立光器件集成度、功耗、成本与量产一致性瓶颈的关键路径。公司已成功开发并量产 400G/800G/1.6T 硅光 TX-PIC 芯片，产品在多家客户端完成验证并实现批量出货，同时提供具备可量产性的硅光单通道 400Gbps 技术路线；另开发激光雷达芯片及基于芯片集成方案的 OCT 芯片，可广泛应用于 AI 集群互联、高速数据中心、工业检测等前沿领域。公司现有员工 190 余人，其中博士 10 余人，研发人员占比超过 60%，核心芯片研发团队深耕硅光领域超过 20 年。获评国家级专精特新「小巨人」企业。旗下数通子公司（子品牌星汉光子，成都）承担扩产任务。","round":"B+ 轮","lastFunding":"2026-09","latestFunding":"B+ 轮 数亿元，本轮融资由四川发展（四川省科创投资集团）领投，杭州凯泰资本、山东省科创集团等机构跟投。资金将重点投向下一代单波 400Gbps 硅光芯片、1.6T/3.2T 硅光探测器芯片，以及 3.2T/6.4T NPO/CPO 与 OIO 芯粒等新产品研发。","latestTech":"以氮化硅为技术底座，已成功开发并量产 400G/800G/1.6T 硅光 TX-PIC 芯片，产品在多家客户端完成验证并实现批量出货；提供具备可量产性的硅光单通道 400Gbps 技术路线；前瞻布局 3.2T/6.4T NPO/CPO 及 OIO 芯粒。","tech":[{"date":"2026-09","title":"完成数亿元 B+ 轮融资，主攻单波 400G 与 CPO 芯粒","kind":"技术","desc":"资金投向下一代单波 400Gbps 硅光芯片、1.6T/3.2T 硅光探测器芯片及 3.2T/6.4T NPO/CPO、OIO 芯粒。"}],"funding":[{"date":"2026-09","round":"B+轮","amount":"数亿元","inv":"四川发展/四川省科创投资集团（领投）、杭州凯泰资本、山东省科创集团等"},{"date":"2025-12","round":"B轮","amount":"2亿元","inv":"未披露"}],"investorsStructured":[{"name":"四川发展（四川省科创投资集团）","role":"lead","round":"B+轮","date":"2026-09","kind":"gov","note":"四川省属国资平台"},{"name":"凯泰资本","role":"follow","round":"B+轮","date":"2026-09","kind":"vc","note":"杭州本土医疗与硬科技基金"},{"name":"山东省科创集团","role":"follow","round":"B+轮","date":"2026-09","kind":"gov","note":"山东省属科创投资平台"}],"executives":[{"name":"刘敬伟","title":"创始人","role":"management","bio":"中国科学院半导体研究所 2005 届微电子学与固体电子学博士，师从余金中博导；毕业后长期任职于京东方，后创立国科光芯，主导氮化硅硅光技术路线。"}],"note":"氮化硅（SiN）路线是与硅（Si）路线并行的国产硅光重要技术分支，低损耗优势显著。数通子品牌「星汉光子」位于成都。"}'::jsonb,now()
)
