INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'铌奥光电',null,'semiconductor','design',false,'B 轮',null,null,null,'2026-08','{"name":"铌奥光电","industry":"semiconductor","seg":"design","listed":false,"desc":"江苏铌奥光电科技有限公司（2020-07 成立，总部南京），专注于薄膜铌酸锂（TFLN）调制器及相关高端光芯片的设计、研发和销售，是全球极少数掌握薄膜铌酸锂光芯片全链条核心技术并实现规模量产的领军企业。创始团队包含多名光电子领域知名科学家和业界资深产业人士，在薄膜铌酸锂领域进行了长期研究并取得重大技术突破。薄膜铌酸锂本质上是对传统铌酸锂材料的「芯片化改造」——传统铌酸锂具备优异的线性电光效应、低光学损耗和高稳定性，但难以小型化和集成化；薄膜化之后在保留高速、低损耗、高线性度的同时，大幅提升器件集成度和工艺一致性，调制器带宽可达 108GHz（显著优于硅光方案的 67GHz），被公认为冲击 3.2T 速率的核心技术路线。公司已构建基于薄膜铌酸锂的新一代光子芯片设计、制造和封装平台，具备大规模量产及交付能力。多款核心产品实现规模化商业应用，包括：用于 AI 集群 Scale out 短距光互联的 800G/1.6T/3.2T IMDD 光芯片、用于 AI 集群 Scale across 和电信骨干网长距光互联的 800G/1.6T ZR 相干光芯片，以及 67/110GHz 超高带宽强度调制器，产品全面覆盖超高速光互联核心场景。已与多家全球头部科技企业达成深度战略合作。","round":"B 轮","lastFunding":"2026-08","latestFunding":"B 轮 数亿元，本轮由高瓴创投、云锋基金、诚通科创、国开科创、沃赋资本、盛赫资本、观新光源、联想创投、南芯科创、粤财创投等多家投资机构参与投资；公司原有股东南京市创新投资、金浦资本、毅达资本、广州产投继续追加投资。资金将重点投向薄膜铌酸锂光芯片大规模量产线建设，以及下一代 AI 光互联前沿技术研发攻坚。","latestTech":"薄膜铌酸锂调制器带宽可达 108GHz（硅光方案为 67GHz），被公认为冲击 3.2T 速率的核心路线；已实现 67/110GHz 超高带宽强度调制器、800G/1.6T/3.2T IMDD 光芯片及 800G/1.6T ZR 相干光芯片的规模化商业应用。","tech":[{"date":"2026-08","title":"完成数亿元 B 轮，全速推进薄膜铌酸锂光芯片量产","kind":"量产","desc":"产品已进入 AI 集群 Scale out/Scale across 与电信骨干网长距光互联场景，与多家全球头部科技企业战略合作。"}],"funding":[{"date":"2026-08","round":"B轮","amount":"数亿元","inv":"高瓴创投、云锋基金、诚通科创、国开科创、沃赋资本、盛赫资本、观新光源、联想创投、南芯科创、粤财创投；老股东南京市创新投资、金浦资本、毅达资本、广州产投追加"}],"investorsStructured":[{"name":"高瓴创投","role":"lead","round":"B轮","date":"2026-08","kind":"vc"},{"name":"云锋基金","role":"lead","round":"B轮","date":"2026-08","kind":"pe"},{"name":"联想创投","role":"strategic","round":"B轮","date":"2026-08","kind":"cvc"},{"name":"国开科创","role":"follow","round":"B轮","date":"2026-08","kind":"gov","note":"国家开发银行旗下科创投资平台"},{"name":"诚通科创","role":"follow","round":"B轮","date":"2026-08","kind":"gov","note":"中国诚通系"},{"name":"粤财创投","role":"follow","round":"B轮","date":"2026-08","kind":"gov","note":"广东省属国资"},{"name":"南京市创新投资集团","role":"follow","round":"B轮","date":"2026-08","kind":"gov","note":"连续多轮加注"},{"name":"毅达资本","role":"follow","round":"B轮","date":"2026-08","kind":"vc","note":"老股东追加"},{"name":"金浦资本","role":"follow","round":"B轮","date":"2026-08","kind":"pe","note":"老股东追加"},{"name":"广州产投","role":"follow","round":"B轮","date":"2026-08","kind":"gov","note":"老股东追加"},{"name":"沃赋资本","role":"follow","round":"B轮","date":"2026-08","kind":"vc"},{"name":"南芯科创","role":"follow","round":"B轮","date":"2026-08","kind":"vc"}],"note":"薄膜铌酸锂（TFLN）被公认为冲击 3.2T 的核心路线，同赛道池内另有元芯光电子、犀里光电（均未入库）。"}'::jsonb,now()
)
