INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'犀里光电',null,'semiconductor','design',false,'Pre-A 轮',null,null,null,'2026-09','{"name":"犀里光电","industry":"semiconductor","seg":"design","listed":false,"desc":"犀里光电科技（杭州）有限责任公司（2025-01 成立，总部浙江省杭州市余杭区），主营薄膜铌酸锂（TFLN）光子芯片调制器研发、生产及销售。创始人王骋拥有清华大学微电子学学士和哈佛大学电子工程博士学位，师从薄膜铌酸锂光子技术开创者 Marko Lončar 教授，曾参与创办 HyperLight，后任教于香港城市大学，是全球薄膜铌酸锂光子技术主要开创者之一；核心团队来自哈佛大学、香港城市大学和中科院，具备八年协作基础，覆盖材料研发、晶圆级工艺、芯片设计及器件工程化等全栈能力。公司以薄膜铌酸锂为核心平台，围绕晶圆级工艺、光子芯片设计、器件工程化及片上系统光子引擎构建平台化技术体系，形成多波长频梳光源、高速电光调制芯片、相干 IQ 调制芯片及光子引擎的产品布局。当前产品支持单波 400G 及 1.6T/3.2T 速率，具备超高速电光响应、低驱动电压与低损耗特性，通过统一晶圆级工艺与设计能力实现底层技术跨产品复用，支撑机架内至城域全场景光互联需求，覆盖 AI 数据中心 Scale Up、Scale Out 与 Scale Across 多层互联场景，同步适配 6G、低空经济及量子技术等前沿赛道。公司已搭建材料研发、晶圆协同加工到系统产品落地的完整产业闭环，并在香港完成实地部署，商业化路径经实战验证具备规模化复制基础。","round":"Pre-A 轮","lastFunding":"2026-09","latestFunding":"Pre-A 轮 亿元级，由孚腾资本领投，上海未来产业基金、基石资本、大湾区基金、FutureX 天际资本、深产投及上市公司智微智能跟投。资金主要用于薄膜铌酸锂光子芯片及片上系统集成技术持续研发，推进核心产品迭代、晶圆级工艺协同及量产验证。","latestTech":"产品支持单波 400G 及 1.6T/3.2T 速率，具备超高速电光响应、低驱动电压与低损耗特性；通过统一晶圆级工艺与设计能力实现底层技术跨产品复用。","tech":[{"date":"2026-09","title":"完成亿元级 Pre-A 轮，推进晶圆级工艺协同与量产验证","kind":"量产","desc":"加速与 AI 数据中心、光模块、通信设备和光电封测等产业链伙伴合作。"}],"funding":[{"date":"2026-09","round":"Pre-A轮","amount":"亿元级","inv":"孚腾资本（领投）、上海未来产业基金、基石资本、大湾区基金、FutureX 天际资本、深产投、智微智能"}],"investorsStructured":[{"name":"孚腾资本","role":"lead","round":"Pre-A轮","date":"2026-09","kind":"gov","note":"上海国投旗下"},{"name":"上海未来产业基金","role":"follow","round":"Pre-A轮","date":"2026-09","kind":"gov"},{"name":"基石资本","role":"follow","round":"Pre-A轮","date":"2026-09","kind":"pe"},{"name":"大湾区基金","role":"follow","round":"Pre-A轮","date":"2026-09","kind":"gov"},{"name":"FutureX 天际资本","role":"follow","round":"Pre-A轮","date":"2026-09","kind":"vc"},{"name":"深产投","role":"follow","round":"Pre-A轮","date":"2026-09","kind":"gov","note":"深圳市属产业投资平台"},{"name":"智微智能","role":"strategic","round":"Pre-A轮","date":"2026-09","kind":"cvc","note":"上市公司产业投资"}],"executives":[{"name":"王骋","title":"创始人","role":"management","bio":"清华大学微电子学学士、哈佛大学电子工程博士，师从 Marko Lončar 教授，曾参与创办 HyperLight，后任教于香港城市大学；全球薄膜铌酸锂光子技术主要开创者之一。"}],"note":"成立仅半年即完成亿元级 Pre-A 轮；据财联社创投通—执中数据，以 2026 年 9 月为基准，后续 2 年融资预测概率 82.76%。"}'::jsonb,now()
)
