INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'芯速联',null,'semiconductor','design',false,'B++ 轮',null,null,null,'2026-09','{"name":"芯速联","industry":"semiconductor","seg":"design","listed":false,"desc":"芯速联光电科技（杭州）有限公司（2019 年成立，总部杭州，另设宁波芯速联光电科技），专注于高速光通信领域，以硅光芯片自主研发创新为核心，主营业务覆盖高速硅光芯片设计、封装及测试，并致力提供光引擎及光模块整体解决方案，是国家高新技术企业、省级专精特新企业。公司已实现从硅光芯片设计、外延工艺到模块封装测试的垂直整合，800G/1.6T 硅光芯片及模块已具备量产能力。自研的硅光调制芯片在关键性能指标上均远超国际标准，可适配从 400G 到 1.6T 的主流光模块需求，并支持长达 10 公里的传输距离，产品已通过海外头部客户验证，广泛应用于 AI 智算中心、超算中心、云计算、5G 通信等领域。2026 年 9 月获得国调基金战略投资，是国调基金在高速光通信领域的重要布局，锚定集成电路和新型信息技术服务、支持高端光通信芯片国产替代的具体举措。","round":"B++ 轮","lastFunding":"2026-09","latestFunding":"B++ 轮，由诚通基金管理的国调基金完成战略投资，支持企业加快高速硅光芯片与硅光模块产业化落地，助力我国 AI 算力底座关键核心技术实现自主可控。金额未披露。","latestTech":"800G/1.6T 硅光芯片及模块已具备量产能力，自研硅光调制芯片关键性能指标远超国际标准，支持长达 10 公里传输距离。","funding":[{"date":"2026-09","round":"B++轮","inv":"国调基金（诚通基金管理）"}],"investorsStructured":[{"name":"国调基金","role":"strategic","round":"B++轮","date":"2026-09","kind":"gov","note":"诚通基金管理的国家级基金，服务「东数西算」与国家级数字基础设施建设"}],"note":"国调基金投资意在保障国产算力产业链安全稳定，并与相关国资央企协同。"}'::jsonb,now()
)
