INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'慧芯激光',null,'semiconductor','design',false,'A2+ 轮',null,null,null,'2026','{"name":"慧芯激光","industry":"semiconductor","seg":"design","listed":false,"desc":"福建慧芯激光科技有限公司（2019 年成立，总部福建泉州），专注于人工智能高端光芯片的研发、制造与销售，以 IDM 模式为基础，同时提供标准设计的外延片生长及芯片制程代工服务。公司是少数同时拥有 6 英寸砷化镓（GaAs）与 4 英寸磷化铟（InP）双材料体系 IDM 全流程产线的企业，建成国内首条 6 英寸砷化镓加 4 英寸磷化铟的双材料 IDM 产线。产品覆盖 VCSEL、EML、CW DFB 等发射端激光器芯片及 PD、APD 等接收端探测器芯片，实现收发全链路覆盖，全面覆盖 AI 算力中心、数据中心、车载光通信及激光雷达等领域。产品进度：①高速系列——56G/112G VCSEL 已实现量产，200G VCSEL 开发顺利、3dB 带宽突破 40GHz；②光源系列——70mW/100mW CW DFB 已实现量产，更高功率 CW DFB 将在年内陆续推出，该系列已斩获多项海内外订单；③长距系列——100G/200G EML 与海外合作伙伴深度协同推进；④探测器系列——基于 GaAs 和 InP 的 100G 探测器芯片均已达到量产状态。此外，面向车载光通信、满足 -55℃~125℃ 宽温工作的 850nm/910nm/980nm VCSEL 芯片及配套 PD 芯片均已通过客户验证。随着数据中心向 800G/1.6T 跃迁并开启 3.2T 及以上预研，高速 VCSEL、EML 及 CW DFB 成为算力互联关键瓶颈，公司为国产替代核心标的。","round":"A2+ 轮","lastFunding":"2026","latestFunding":"A2+ 轮 数亿元人民币，由国中资本领投，贵州高新基金、隐山资本、敦成投资、财鑫资本、文投创工场和明礼泽华等机构联合参与，资金将主要用于扩充设备及提升产能、研发下一代高端光芯片产品。公司一年内连下三轮融资。","latestTech":"国内首条 6 英寸 GaAs 加 4 英寸 InP 双材料 IDM 全流程产线；56G/112G VCSEL 量产、200G VCSEL 3dB 带宽突破 40GHz；70mW/100mW CW DFB 量产，GaAs 与 InP 100G 探测器均达量产状态。","tech":[{"date":"2026","title":"建成国内首条 6 英寸砷化镓 + 4 英寸磷化铟双材料 IDM 产线","kind":"产能","desc":"实现收发全链路光芯片覆盖，补国内高速光芯片产能短板。"}],"funding":[{"date":"2026","round":"A2+轮","amount":"数亿元","inv":"国中资本（领投）、贵州高新基金、隐山资本、敦成投资、财鑫资本、文投创工场、明礼泽华"}],"investorsStructured":[{"name":"国中资本","role":"lead","round":"A2+轮","date":"2026","kind":"vc","note":"国家级中小企业发展基金背景"},{"name":"贵州高新基金","role":"follow","round":"A2+轮","date":"2026","kind":"gov"},{"name":"隐山资本","role":"follow","round":"A2+轮","date":"2026","kind":"pe","note":"普洛斯旗下"},{"name":"敦成投资","role":"follow","round":"A2+轮","date":"2026","kind":"pe"},{"name":"财鑫资本","role":"follow","round":"A2+轮","date":"2026","kind":"vc"},{"name":"文投创工场","role":"follow","round":"A2+轮","date":"2026","kind":"gov"},{"name":"明礼泽华","role":"follow","round":"A2+轮","date":"2026","kind":"vc"}],"note":"EML 与磷化铟是 25G 以上高速光芯片国产化率最低的环节（高端 EML 国产化率不足 10%），政策目标 2028 年核心光芯片自主可控率不低于 70%，国产替代窗口期约 2-3 年。"}'::jsonb,now()
)
