INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'芯光界',null,'semiconductor','design',false,'A 轮',null,null,null,'2026-09','{"name":"芯光界","industry":"semiconductor","seg":"design","listed":false,"desc":"芯光界智能科技（上海）有限公司（2026-05 成立，总部上海），聚焦前沿光互连和硅光通信技术的创新研发与成果转化，成立不到 5 个月已完成 5 轮融资，是光互连赛道融资节奏最快的初创企业之一。创始人兼 CEO 董坡博士毕业于麦吉尔大学，并在康奈尔大学纳米光子学小组完成博士后研究，是美国电气电子工程师学会（IEEE）、美国光学学会（Optica）Fellow：2008 年起在 Kotura 担任首席工程师/科学家，2010 年就职于诺基亚贝尔实验室、出任硅光子研究部门负责人，2019 年起在 II-VI 任职高级总监、Fellow，2025 年 II-VI 被 Coherent 收购后出任 Coherent 硅光技术副总裁，2026 年在上海创立芯光界，拥有从硅光基础器件研发到产业化落地的全链条经验。核心骨干均具备 15 年以上头部企业研发、量产及项目交付经验，覆盖 PIC 硅光芯片设计、EIC 电芯片、光学组装与封装、光模块架构到 NPO 系统架构的完整链路；核心研发团队中硕士及以上学历占比超 80%，博士占比超三成，成员来自耶鲁、康奈尔、北京大学、复旦大学、浙江大学、中科院等。首款 NPO 光引擎已与国内头部 GPU 厂商及数据中心客户启动技术方案对接与验证；公司构建了从芯片设计、封装耦合到系统级信号完整性的全链路自研能力，并参与 ODCC、OPEN CPX MSA 等核心行业标准制定。","round":"A 轮","lastFunding":"2026-09","latestFunding":"Pre-A 轮和 A 轮累计金额近 10 亿元，两轮融资包含华映资本、Lumicore、九天创投、Glory Ventures III、Redpoint、前海启航、松禾资本等 20 多家投资机构。加上这两轮，公司成立不到 5 个月已完成 5 轮融资。资金主要用于：持续投入 NPO/CPO 产品研发；建设高级别实验室，打通从设计、测试到耦合封装、可靠性验证的自主闭环；扩充研发团队；为后续量产做好产能与供应链准备。","latestTech":"首款 NPO 光引擎已与国内头部 GPU 厂商及数据中心客户启动技术方案对接与验证；构建从芯片设计、封装耦合到系统级信号完整性的全链路自研能力，参与 ODCC、OPEN CPX MSA 等核心行业标准制定。","tech":[{"date":"2026-09","title":"完成 Pre-A 与 A 轮累计近 10 亿元融资","kind":"融资","desc":"成立不到 5 个月完成 5 轮融资，建设从设计、测试到耦合封装、可靠性验证的自主闭环。"}],"funding":[{"date":"2026-09","round":"A轮/Pre-A轮","amount":"近10亿元（累计）","inv":"华映资本、Lumicore、九天创投、Glory Ventures III、Redpoint、前海启航、松禾资本等 20 多家机构"},{"date":"2026-09","round":"天使+轮","inv":"华映资本、知识城创投、松禾资本、普罗资本等"},{"date":"2026-08","round":"天使轮","amount":"约1亿元","inv":"启明创投"}],"investorsStructured":[{"name":"启明创投","role":"lead","round":"天使轮","date":"2026-08","kind":"vc","note":"约 1 亿元"},{"name":"华映资本","role":"lead","round":"A轮/Pre-A轮","date":"2026-09","kind":"vc"},{"name":"Lumicore","role":"strategic","round":"A轮/Pre-A轮","date":"2026-09","kind":"cvc","note":"产业方"},{"name":"Redpoint","role":"follow","round":"A轮/Pre-A轮","date":"2026-09","kind":"vc","note":"红点创投"},{"name":"松禾资本","role":"follow","round":"天使+/A轮","date":"2026-09","kind":"vc"},{"name":"前海启航","role":"follow","round":"A轮/Pre-A轮","date":"2026-09","kind":"gov"},{"name":"知识城创投","role":"follow","round":"天使+轮","date":"2026-09","kind":"gov"},{"name":"普罗资本","role":"follow","round":"天使+轮","date":"2026-09","kind":"vc"},{"name":"九天创投","role":"follow","round":"A轮/Pre-A轮","date":"2026-09","kind":"vc"},{"name":"Glory Ventures III","role":"follow","round":"A轮/Pre-A轮","date":"2026-09","kind":"vc"}],"executives":[{"name":"董坡","title":"创始人兼 CEO","role":"management","bio":"麦吉尔大学博士，康奈尔大学纳米光子学小组博士后，IEEE 与 Optica Fellow；曾任 Kotura 首席工程师/科学家、诺基亚贝尔实验室硅光子研究部门负责人、II-VI 高级总监与 Fellow、Coherent 硅光技术副总裁（2025 年），2026 年在上海创立芯光界。"}],"note":"NPO/CPO 片间光互连是光互连最前沿方向，对标池内光联芯科（OIO 赛道国内首家独角兽，投后估值超 10 亿美元）。"}'::jsonb,now()
)
