INSERT INTO research_companies (name,code,industry,seg,listed,round,cap,valuation,rev,last_funding,data,updated_at) VALUES (
'驿天诺',null,'semiconductor','equipment',false,'A+ 轮',null,null,null,'2026','{"name":"驿天诺","industry":"semiconductor","seg":"equipment","listed":false,"desc":"武汉驿天诺科技有限公司（2009-04 成立，总部武汉），由东隆科技集团与中科院西安光机所光电子集成电路先导技术研究院合资创办，专注光电子集成测试及封装解决方案的高新技术企业。公司自 2019 年起明确战略转型，依托光电集成与半导体封测技术积累，开发覆盖晶圆级、芯片级到器件级的光电测试与耦合封装设备，为硅光、薄膜铌酸锂、III-V 族及第三代半导体客户提供高精度、高可靠性的国产装备与自动化产线方案。以「核心零部件自研+端到端封测系统」为核心技术路线，通过自研电机运控、测试仪表、透镜光纤耦合模组及机器视觉算法，构建「机台+仪表+软件+数据库」一体化交付能力。产品矩阵包括晶圆光电测试探针台、硅光芯片测试台、全自动耦合封装系统、自动晶圆缺陷目检台及高功率晶圆测试台等，支持 2-12 寸晶圆、亚微米级定位精度与秒级单芯片测试节拍，可灵活适配硅光 PIC、CPO 光引擎、功率器件等多类封测场景。2022 年曾与九峰山实验室联合交付国内首套高功率晶圆封测设备。公司产品已在国内多家头部光模块厂、硅光芯片企业及科研院所产线验证并规模化部署，晶圆光电测试系统国内市占率约 40%-50%，服务覆盖光通信、AI 算力互连、量子计算及人形机器人等方向。","round":"A+ 轮","lastFunding":"2026","latestFunding":"2026 年先后完成数千万元 A 轮融资（张江浩成领投、雍邑光电跟投）及数亿元人民币 A+ 轮融资（君联资本、华工瑞源参投）；资金用于加速硅光/CPO 测试封装设备研发迭代、核心部件自主化替代与海内外市场渗透。","latestTech":"自研电机运控、测试仪表、透镜光纤耦合模组及机器视觉算法，构建「机台+仪表+软件+数据库」一体化交付能力；产品支持 2-12 寸晶圆、亚微米级定位精度与秒级单芯片测试节拍。","tech":[{"date":"2026","title":"完成 A 轮与 A+ 轮融资，加速硅光/CPO 测试封装设备研发","kind":"技术","desc":"资金投向核心部件自主化替代与海内外市场渗透，巩固光电集成封测装备国产替代位置。"},{"date":"2022","title":"与九峰山实验室联合交付国内首套高功率晶圆封测设备","kind":"量产","desc":"进入国内头部光模块厂与硅光芯片企业产线，规模化部署。"}],"funding":[{"date":"2026","round":"A+轮","amount":"数亿元","inv":"君联资本、华工瑞源"},{"date":"2026","round":"A轮","amount":"数千万元","inv":"张江浩成（领投）、雍邑光电（跟投）"}],"investorsStructured":[{"name":"君联资本","role":"lead","round":"A+轮","date":"2026","kind":"vc"},{"name":"华工瑞源","role":"follow","round":"A+轮","date":"2026","kind":"cvc","note":"华工科技系产业资本"},{"name":"张江浩成","role":"lead","round":"A轮","date":"2026","kind":"gov","note":"上海张江高科旗下"},{"name":"雍邑光电","role":"strategic","round":"A轮","date":"2026","kind":"cvc","note":"光模块产业方"}],"note":"光电测试与耦合封装设备是硅光/CPO 产业链国产化率最低的环节之一，公司晶圆光电测试系统国内市占率约 40%-50%，属细分隐形冠军。"}'::jsonb,now()
)
